-- usage: luajit unit.lua <loader.lua> <vectors.lua>
-- vectors.lua is generated by test_loader.py and returns a table of cases
package.path = arg[0]:gsub("[^/]+$", "") .. "?.lua;" .. package.path
local json = require("json")

__NL_LOADER_TEST = true
local L = dofile(arg[1])
local V = dofile(arg[2])

local failures = 0
local function check(cond, label)
    if not cond then
        failures = failures + 1
        io.stderr:write("FAIL " .. label .. "\n")
    end
end

for i, c in ipairs(V.sha512) do
    check(L.hex_encode(L.sha512(c.msg)) == c.hex, "sha512 #" .. i .. " len=" .. #c.msg)
end

for i, c in ipairs(V.ed25519) do
    local got = L.ed25519_verify(L.hex_decode(c.pk), L.hex_decode(c.sig), c.msg)
    check(got == c.valid, ("ed25519 #%d (%s) expected %s got %s"):format(i, c.label, tostring(c.valid), tostring(got)))
end

for i, c in ipairs(V.b64) do
    check(L.b64decode(c.input) == c.output, "b64 #" .. i .. " " .. tostring(c.input))
end

local pk = L.hex_decode(V.envelope_pk)
for i, c in ipairs(V.envelopes) do
    local p, why = L.open_envelope(pk, c.body, c.expect, json.parse)
    if c.ok then
        check(p ~= nil, ("envelope #%d (%s) should pass, got: %s"):format(i, c.label, tostring(why)))
    else
        check(p == nil, ("envelope #%d (%s) should fail"):format(i, c.label))
        if p == nil and c.reason then
            check(why:find(c.reason, 1, true) ~= nil,
                ("envelope #%d (%s) wrong reason: %s"):format(i, c.label, tostring(why)))
        end
    end
end

-- compiler: bytecode refused, sandbox hides dangerous globals
local bc = string.dump(function() return 1 end)
check(L.compile(bc, "=bc", {}) == nil, "bytecode must be refused")
local env = L.make_env(_G)
local fn = assert(L.compile("return debug, getfenv, loadstring, load, print ~= nil", "=t", env))
local a, b, c, d, e = fn()
check(a == nil and b == nil and c == nil and d == nil and e == true, "sandbox globals")
local fn2 = assert(L.compile("x_global_from_child = 1", "=t", env))
fn2()
check(rawget(_G, "x_global_from_child") == nil, "child globals must not leak into loader env")

if failures > 0 then
    io.stderr:write(failures .. " failure(s)\n")
    os.exit(1)
end
print("lua unit tests passed")
